    //     0 ≤ i ≤ p,
    //     res.len() == i,
    //     and for every j < i, we have already done the correct
    //     “triplet‐rotate” assignment into res[j].
    //   decreases: p − i
    //
    let mut i: usize = 0;
    while i < p {
        #[invariant(i <= p)]
        #[invariant(res.len() == i)]
        #[invariant(
            forall(|j: usize|
                j < i ==>
                  if j % 3 == 0 {
                    res[j] == s[j + 2]
                  } else {
                    res[j] == s[j - 1]
                  }
            )
        )]
        #[decreases(p - i)]
        {
            // now do the i’th step
            if i % 3 == 0 {
                res.push(s[i + 2]);
            } else {
                res.push(s[i - 1]);
            }
            i += 1;
        }
    }
    // at this point res.len() == p

    //--------------------------------------------------------------------------
    // Second loop: copy over the leftover suffix [p .. len)
    //
    //   invariant:
    //     p ≤ i2 ≤ len,
    //     res.len() == i2,
    //     and the first p entries of res are correct (we keep the same
    //     invariant about full‐triplets for j < p).
    //   decreases: len − i2
    //
    let mut i2: usize = p;
    while i2 < len {
        #[invariant(p <= i2)]
        #[invariant(i2 <= len)]
        #[invariant(res.len() == i2)]
        #[invariant(
            forall(|j: usize|
                j < p ==>
                  if j % 3 == 0 {
                    res[j] == s[j + 2]
                  } else {
                    res[j] == s[j - 1]
                  }
            )
        )]
        #[decreases(len - i2)]
        {
            res.push(s[i2]);
            i2 += 1;
        }
    }
    // now res.len() == len

